SELECT uint8 = uint16 AS c0, toTypeName(uint8 = uint16) AS t0, uint8 != uint16 AS c1, toTypeName(uint8 != uint16) AS t1, uint8 < uint16 AS c2, toTypeName(uint8 < uint16) AS t2, uint8 <= uint16 AS c3, toTypeName(uint8 <= uint16) AS t3, uint8 > uint16 AS c4, toTypeName(uint8 > uint16) AS t4, uint8 >= uint16 AS c5, toTypeName(uint8 >= uint16) AS t5 FROM he24.numeric ORDER BY row_id
